 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = [r for r, row in enumerate(grid) if 8 in row]
    marker = next((c for c, v in enumerate(grid[0]) if v == 2), w // 2)
    holes_by = [[c for c, v in enumerate(grid[r]) if v == 0] for r in bars]

    # Put color in each opening in the perforated barriers.
    for r, holes in zip(bars, holes_by):
        for c in holes:
            out[r][c] = 2

    # The beam widens from the marker to the first gate. Expansion is limited
    # by the neighboring openings; far from the gate only the source column.
    if bars:
        first = bars[0]
        holes = holes_by[0]
        for r in range(1, first):
            width = first - r
            lo = min([marker] + holes)
            hi = max([marker] + holes)
            a = max(0, min(lo, marker - width))
            b = min(w - 1, max(hi, marker + width))
            for c in range(a, b + 1):
                out[r][c] = 2

    # Between two adjacent gates, the beam fills the corridor between their
    # outer openings. If it contains a full-width barrier further down, the
    # intermediate blank row is fully illuminated.
    for i in range(len(bars) - 1):
        top, bottom = bars[i], bars[i + 1]
        openings = holes_by[i] + holes_by[i + 1]
        if openings:
            a, b = min(openings), max(openings)
            for r in range(top + 1, bottom):
                for c in range(a, b + 1):
                    out[r][c] = 2
        if i == 0 and bottom - top > 2:
            # The gate passages fan out before they reconverge at the next bar.
            for c in range(w):
                out[top + 1][c] = 2

    # Past the last gate, follow its leftmost opening as a narrow ray.
    if bars and holes_by[-1]:
        c = holes_by[-1][0]
        for r in range(bars[-1] + 1, h):
            out[r][c] = 2
    return out
