 "content": "def transform(grid):
    """Propagate a beam through grid walls, splitting at openings and reflecting."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    mr, mc = markers[0]

    # Rotate/flip so the source is on the top edge and rays travel downward.
    if mr == 0:
        a = [row[:] for row in grid]
        undo = lambda z: z
        q0 = mc
    elif mr == h - 1:
        a = grid[::-1]
        undo = lambda z: z[::-1]
        q0 = mc
    elif mc == 0:
        a = [[grid[r][c] for r in range(h)] for c in range(w)]
        undo = lambda z: [[z[c][r] for c in range(w)] for r in range(h)]
        q0 = mr
    else:
        a = [[grid[r][c] for r in range(h - 1, -1, -1)] for c in range(w)]
        undo = lambda z: [[z[c][h - 1 - r] for c in range(w)] for r in range(h)]
        q0 = h - 1 - mr

    d, n = len(a), len(a[0])
    z = [row[:] for row in a]
    beams = {q0}
    # A ray hitting an 8-wall detours on its near side. It then carries on
    # through the closest aperture(s), leaving a colored trail in free cells.
    for r in range(1, d):
        row = a[r]
        next_beams = set()
        for q in beams:
            if row[q] != 8:
                if row[q] == 0:
                    z[r][q] = 2
                next_beams.add(q)
                continue
            apertures = [c for c, v in enumerate(row) if v == 0]
            if not apertures:
                continue
            nearest = min(abs(c - q) for c in apertures)
            for c in (x for x in apertures if abs(x - q) == nearest):
                left = q
                while left > 0 and row[left - 1] == 8:
                    left -= 1
                right = q
                while right + 1 < n and row[right + 1] == 8:
                    right += 1
                for x in range(min(left, c), max(right, c) + 1):
                    if a[r - 1][x] == 0:
                        z[r - 1][x] = 2
                z[r][c] = 2
                next_beams.add(c)
        beams = next_beams
        if not beams:
            break
    return undo(z)
