    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    sr, sc = markers[0]

    # Rotate/reflect so the initial ray points down.
    if sr == 0:
        a = [row[:] for row in grid]
        undo = lambda z: z
        start = (0, sc)
    elif sr == h - 1:
        a = grid[::-1]
        undo = lambda z: z[::-1]
        start = (0, sc)
    elif sc == 0:
        a = [[grid[r][c] for r in range(h)] for c in range(w)]
        undo = lambda z: [[z[c][r] for c in range(w)] for r in range(h)]
        start = (0, sr)
    else:
        a = [[grid[r][c] for r in range(h - 1, -1, -1)] for c in range(w)]
        undo = lambda z: [[z[c][h - 1 - r] for c in range(w)] for r in range(h)]
        start = (0, h - 1 - sr)

    d, n = len(a), len(a[0])
    z = [row[:] for row in a]
    # Each work item is a new ray, beginning at a transparent opening and
    # continuing in the original direction of travel.
    q = deque([start])
    seen_rays = set()
    while q:
        r, c = q.popleft()
        if (r, c) in seen_rays:
            continue
        seen_rays.add((r, c))
        while r + 1 < d:
            nr = r + 1
            if a[nr][c] == 0:
                z[nr][c] = 2
                r = nr
                continue
            if a[nr][c] == 2:
                r = nr
                continue
            # Hit a straight wall. Find its contiguous segment perpendicular
            # to travel, then trace the lane beside it to both ends/openings.
            lo = hi = c
            while lo > 0 and a[nr][lo - 1] == 8:
                lo -= 1
            while hi + 1 < n and a[nr][hi + 1] == 8:
                hi += 1
            lane_r = nr - 1
            for x in range(max(0, lo - 1), min(n - 1, hi + 1) + 1):
                if a[lane_r][x] == 0:
                    z[lane_r][x] = 2
            # Rays pass through any open cells immediately beyond either end.
            for x in (lo - 1, hi + 1):
                if 0 <= x < n and a[nr][x] == 0:
                    z[nr][x] = 2
                    q.append((nr, x))
            break
    return undo(z)


