    out = [row[:] for row in grid]
    bars = [r for r, row in enumerate(grid) if 8 in row]
    holes = [[c for c, value in enumerate(grid[r]) if value == 0] for r in bars]
    if not bars:
        return out

    # Color the transparent apertures in every horizontal barrier.
    for r, gaps in zip(bars, holes):
        for c in gaps:
            out[r][c] = 2

    # The source fans out toward the first barrier's openings.
    source = next((c for c, value in enumerate(grid[0]) if value == 2), w // 2)
    for r in range(1, bars[0]):
        left = min([source] + holes[0])
        right = max([source] + holes[0])
        for c in range(left, right + 1):
            out[r][c] = 2

    # Between successive barriers, channels widen and connect across the
    # interval bounded by the gaps in both barriers. At a two-row spacing,
    # the intervening row is the full bridge; at three-row spacing, the ray
    # travels through the upper gaps and then spreads over the next blank row.
    for i in range(len(bars) - 1):
        top, bottom = bars[i], bars[i + 1]
        if bottom - top == 2:
            gaps = holes[i] + holes[i + 1]
            if gaps:
                for c in range(min(gaps), max(gaps) + 1):
                    out[top + 1][c] = 2
        else:
            for c in holes[i]:
                out[top + 1][c] = 2
            for r in range(top + 2, bottom):
                for c in range(w):
                    out[r][c] = 2

    # Below the last barrier, each surviving opening carries a straight ray.
    for r in range(bars[-1] + 1, h):
        for c in holes[-1]:
            out[r][c] = 2
    return out
