                if grid[rr][c] == 0:
                    out[rr][c] = 2
        # At the wall, color every zero opening. From each incoming lane choose
        # the nearest gap(s), and retain those as the channels below it.
        for c in gaps:
            out[r][c] = 2
        if prev_bar < 0:
            active = set(gaps)
        else:
            active = {min(gaps, key=lambda x: abs(x-a)) for a in active}
        prev_bar = r

