def transform(grid):
    """Trace a straight beam; at each 8-wall, route it around both ends."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    source = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if source is None:
        return out

    sr, sc = source
    if sr == 0:
        dr, dc = 1, 0
    elif sr == h - 1:
        dr, dc = -1, 0
    elif sc == 0:
        dr, dc = 0, 1
    else:
        dr, dc = 0, -1

    rays = deque([source])
    visited = set()
    while rays:
        r, c = rays.popleft()
        while True:
            if (r, c) in visited:
                break
            visited.add((r, c))
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w):
                break

            if grid[nr][nc] != 8:
                if grid[nr][nc] == 0:
                    out[nr][nc] = 2
                r, c = nr, nc
                continue

            # Find the whole contiguous wall segment perpendicular to travel.
            if dr != 0:  # beam vertical, wall segment is horizontal
                lo = hi = nc
                while lo > 0 and grid[nr][lo - 1] == 8:
                    lo -= 1
                while hi + 1 < w and grid[nr][hi + 1] == 8:
                    hi += 1
                # Paint the adjacent incoming-side lane alongside the wall,
                # including the opening just beyond either end when present.
                for x in range(max(0, lo - 1), min(w - 1, hi + 1) + 1):
                    if grid[r][x] == 0:
                        out[r][x] = 2
                exits = [(nr, x) for x in (lo - 1, hi + 1)
                         if 0 <= x < w and grid[nr][x] != 8]
            else:  # beam horizontal, wall segment is vertical
                lo = hi = nr
                while lo > 0 and grid[lo - 1][nc] == 8:
                    lo -= 1
                while hi + 1 < h and grid[hi + 1][nc] == 8:
                    hi += 1
                for y in range(max(0, lo - 1), min(h - 1, hi + 1) + 1):
                    if grid[y][c] == 0:
                        out[y][c] = 2
                exits = [(y, nc) for y in (lo - 1, hi + 1)
                         if 0 <= y < h and grid[y][nc] != 8]

            # Each open endpoint starts a new ray in the original direction.
            for er, ec in exits:
                if grid[er][ec] == 0:
                    out[er][ec] = 2
                rays.append((er, ec))
            break

    return out


