    # extreme openings. For a two-row gap, channels persist for one row and
    # then spread across the intervening space to the next barrier.
    for i in range(len(bars) - 1):
        top, bottom = bars[i], bars[i + 1]
        upper, lower = holes[i], holes[i + 1]
        distance = bottom - top
        if distance == 2:
            if upper and lower:
