 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    source = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if source is None:
        return out
    sr, sc = source
    if sr == 0:
        dr, dc = 1, 0
    elif sr == h - 1:
        dr, dc = -1, 0
    elif sc == 0:
        dr, dc = 0, 1
    else:
        dr, dc = 0, -1

    # Rays move straight until encountering an 8-run. They then follow the
    # incoming-side lane along that run to each endpoint, continuing through
    # any openings there in the original direction.
    rays = deque([(sr, sc, dr, dc)])
    seen = set()
    while rays:
        r, c, dr, dc = rays.popleft()
        while True:
            state = (r, c, dr, dc)
            if state in seen:
                break
            seen.add(state)
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w):
                break
            if grid[nr][nc] != 8:
                if grid[nr][nc] == 0:
                    out[nr][nc] = 2
                r, c = nr, nc
                continue

            if dr != 0:  # vertical travel: obstacle run is horizontal
                lo = hi = nc
                while lo > 0 and grid[nr][lo - 1] == 8:
                    lo -= 1
                while hi + 1 < w and grid[nr][hi + 1] == 8:
                    hi += 1
                for end in (lo - 1, hi + 1):
                    if not 0 <= end < w:
                        continue
                    for x in range(min(c, end), max(c, end) + 1):
                        if grid[r][x] == 0:
                            out[r][x] = 2
                    if grid[nr][end] == 0:
                        out[nr][end] = 2
                        rays.append((nr, end, dr, dc))
            else:  # horizontal travel: obstacle run is vertical
                lo = hi = nr
                while lo > 0 and grid[lo - 1][nc] == 8:
                    lo -= 1
                while hi + 1 < h and grid[hi + 1][nc] == 8:
                    hi += 1
                for end in (lo - 1, hi + 1):
                    if not 0 <= end < h:
                        continue
                    for y in range(min(r, end), max(r, end) + 1):
                        if grid[y][c] == 0:
                            out[y][c] = 2
                    if grid[end][nc] == 0:
                        out[end][nc] = 2
                        rays.append((end, nc, dr, dc))
            break
    return out


