def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    r0, c0 = markers[0]
    if r0 == 0:
        dr, dc = 1, 0
    elif r0 == h - 1:
        dr, dc = -1, 0
    elif c0 == 0:
        dr, dc = 0, 1
    else:
        dr, dc = 0, -1

    # Follow rays in their original direction. At a wall, paint the parallel
    # lane beside the entire 8-run (including its end openings), then continue
    # from each opening around the run.
    queue = deque([(r0, c0, dr, dc)])
    seen = set()
    while queue:
        r, c, dr, dc = queue.popleft()
        while True:
            state = (r, c, dr, dc)
            if state in seen:
                break
            seen.add(state)
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w):
                break
            if grid[nr][nc] != 8:
                if grid[nr][nc] == 0:
                    out[nr][nc] = 2
                r, c = nr, nc
                continue

            if dr != 0:  # vertical ray meets a horizontal 8-run
                lo = hi = nc
                while lo > 0 and grid[nr][lo - 1] == 8:
                    lo -= 1
                while hi + 1 < w and grid[nr][hi + 1] == 8:
                    hi += 1
                side = r
                for x in range(max(0, lo - 1), min(w - 1, hi + 1) + 1):
                    if grid[side][x] == 0:
                        out[side][x] = 2
                ends = [x for x in (lo - 1, hi + 1)
                        if 0 <= x < w and grid[nr][x] == 0]
                for x in ends:
                    out[nr][x] = 2
                    queue.append((nr, x, dr, dc))
            else:  # horizontal ray meets a vertical 8-run
                lo = hi = nr
                while lo > 0 and grid[lo - 1][nc] == 8:
                    lo -= 1
                while hi + 1 < h and grid[hi + 1][nc] == 8:
                    hi += 1
                side = c
                for y in range(max(0, lo - 1), min(h - 1, hi + 1) + 1):
                    if grid[y][side] == 0:
                        out[y][side] = 2
                ends = [y for y in (lo - 1, hi + 1)
                        if 0 <= y < h and grid[y][nc] == 0]
                for y in ends:
                    out[y][nc] = 2
                    queue.append((y, nc, dr, dc))
            break
    return out


